import { getBoss, closeBoss } from "@/lib/jobs/boss";
import { logger } from "@/lib/logger";
import { getApiTokenCount } from "@/lib/front";
import { handleSyncFrontAccounts } from "./handlers/sync-front-accounts";
import { handleSyncFrontContacts } from "./handlers/sync-front-contacts";
import { handleSyncFrontAccountContacts } from "./handlers/sync-front-account-contacts";
import { handleSyncFrontConversations } from "./handlers/sync-front-conversations";
import { handleSyncFrontAccountConversations } from "./handlers/sync-front-account-conversations";
import { handleSyncProductboardCompanies } from "./handlers/sync-productboard-companies";
import { handleSyncProductboardNotes } from "./handlers/sync-productboard-notes";
import { handleSyncProductboardFeatures } from "./handlers/sync-productboard-features";
import { handleSyncFrontCustomerConversations } from "./handlers/sync-front-customer-conversations";
import { handleSyncProductboardCustomerNotes } from "./handlers/sync-productboard-customer-notes";
import { handleImportConsumption } from "./handlers/import-consumption";
import { handleDetectUsageDrops } from "./handlers/detect-usage-drops";
import { cleanupStaleJobs } from "@/lib/jobs/cleanup";

async function startWorker() {
  try {
    logger.log("Starting pg-boss worker...");
    const boss = await getBoss();

    // Clean up any stale jobs from previous runs
    logger.log("Cleaning up stale jobs...");
    await cleanupStaleJobs();

    // Create queues before registering workers
    const queues = [
      "sync-front-accounts",
      "sync-front-contacts",
      "sync-front-account-contacts",
      "sync-front-conversations",
      "sync-front-account-conversations",
      "sync-front-customer-conversations",
      "sync-productboard-companies",
      "sync-productboard-notes",
      "sync-productboard-customer-notes",
      "sync-productboard-features",
      "import-consumption",
      "detect-usage-drops",
    ];

    logger.log("Creating job queues...");
    for (const queue of queues) {
      await boss.createQueue(queue);
    }

    // Register job handlers
    await boss.work("sync-front-accounts", handleSyncFrontAccounts);
    await boss.work("sync-front-contacts", handleSyncFrontContacts);
    await boss.work("sync-front-conversations", handleSyncFrontConversations);

    // Register sub-job handlers with concurrency options
    const frontConcurrency = 3 * Math.max(1, getApiTokenCount());
    logger.log(`[Worker] Front sub-job concurrency: ${frontConcurrency} (${Math.max(1, getApiTokenCount())} API key(s))`);

    await boss.work(
      "sync-front-account-contacts",
      {
        localConcurrency: frontConcurrency,
      },
      handleSyncFrontAccountContacts
    );

    await boss.work(
      "sync-front-account-conversations",
      {
        localConcurrency: frontConcurrency,
      },
      handleSyncFrontAccountConversations
    );

    await boss.work("sync-productboard-companies", handleSyncProductboardCompanies);
    await boss.work("sync-productboard-notes", handleSyncProductboardNotes);
    await boss.work("sync-productboard-features", handleSyncProductboardFeatures);
    await boss.work("sync-front-customer-conversations", handleSyncFrontCustomerConversations);
    await boss.work("sync-productboard-customer-notes", handleSyncProductboardCustomerNotes);
    await boss.work("import-consumption", handleImportConsumption);
    await boss.work("detect-usage-drops", handleDetectUsageDrops);

    logger.log("✓ Worker started successfully, listening for jobs...");

    // Handle graceful shutdown
    process.on("SIGINT", async () => {
      logger.log("\nShutting down worker...");
      await closeBoss();
      process.exit(0);
    });

    process.on("SIGTERM", async () => {
      logger.log("\nShutting down worker...");
      await closeBoss();
      process.exit(0);
    });
  } catch (error) {
    console.error("Failed to start worker:", error);
    process.exit(1);
  }
}

startWorker();

